-- V2.5: owner-aware fixed lots.
create or replace function public.host_seed_lots(p_room_id text,p_host_secret text,p_lots jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare rid text:=upper(p_room_id); begin
 perform 1 from rooms where id=rid and host_secret=p_host_secret for update;
 if not found then raise exception '主持人权限无效'; end if;
 insert into invites(room_id,code,label) select rid,upper(v->>'owner'),upper(v->>'owner') from jsonb_array_elements(p_lots) v where nullif(v->>'owner','') is not null group by upper(v->>'owner') on conflict(room_id,code) do nothing;
 insert into lots(room_id,id,title,description,start_price,min_increment,consigner_invite_id,sort_order)
 select rid,(v->>'id')::integer,v->>'title',coalesce(v->>'desc',''),(v->>'start')::bigint,(v->>'step')::bigint,i.id,(v->>'id')::integer
 from jsonb_array_elements(p_lots) v left join invites i on i.room_id=rid and i.code=upper(v->>'owner')
 on conflict(room_id,id) do nothing;
end $$;
grant execute on function public.host_seed_lots(text,text,jsonb) to anon,authenticated;

